from pathlib import Path
import json, html
O=Path(__file__).resolve().parent
ESC=html.escape
STYLE='''*{box-sizing:border-box}body{margin:0;padding:32px;background:#f5f5f5;color:#2d3142;font-family:'Geist',system-ui,sans-serif}main{max-width:1320px;margin:auto}h1{font:400 34px 'Instrument Serif',Georgia,serif;margin:8px 0 20px}h2{font-size:23px}p,li{line-height:1.6;max-width:95ch}a{color:#2e5aa8}nav{display:flex;gap:16px;flex-wrap:wrap}.diagram-container{width:100%;overflow-x:auto}svg{width:100%;min-width:1280px;display:block}.node-name{font:600 18px 'Geist',system-ui,sans-serif;fill:#2d3142}.sub{font:14px 'Geist Mono',ui-monospace,monospace;fill:#4f5d75}.tag{font:12px 'Geist Mono',ui-monospace,monospace;fill:#5a6580;letter-spacing:1px}.edge{fill:none;stroke:#4f5d75;stroke-width:1.5}.label{font:13px 'Geist Mono',ui-monospace,monospace;fill:#4f5d75}section{margin:36px 0;border-top:1px solid #ccd0d7;padding-top:24px}table{border-collapse:collapse;width:100%}th,td{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid #ccd0d7}pre{overflow:auto;background:#ececec;padding:18px;font:13px/1.5 ui-monospace,monospace}summary{cursor:pointer}footer{font-size:13px;color:#4f5d75}@media(max-width:600px){body{padding:16px}}@media print{.diagram-container{overflow:visible}svg{min-width:0}nav{display:none}section{break-inside:avoid}}'''
figures=[]
def text(x,y,s,cls='sub',anchor='start'):return f'<text x="{x}" y="{y}" class="{cls}" text-anchor="{anchor}">{ESC(s)}</text>'
def node(i,x,y,w,h,name,lines=[],accent=False,tag='COMPONENT'):
 s=f'<g data-node="{i}"><rect class="node-box" x="{x}" y="{y}" width="{w}" height="{h}" rx="6" fill="{ "#f8ece7" if accent else "#f5f5f5"}" stroke="{ "#bf4520" if accent else "#7c8493"}"/>'
 s+=text(x+16,y+24,tag,'tag')+text(x+16,y+52,name,'node-name')
 for k,line in enumerate(lines):s+=text(x+16,y+80+22*k,line)
 return s+'</g>'
def line(x1,y1,x2,y2,arrow=True,dash=False):return f'<line class="edge" x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}"'+(' marker-end="url(#arrow)"' if arrow else '')+(' stroke-dasharray="5,4"' if dash else '')+'/>'
def path(d,arrow=True):return f'<path class="edge" d="{d}"'+(' marker-end="url(#arrow)"' if arrow else '')+'/>'
def label(x,y,s):return f'<rect x="{x-len(s)*4.2-8}" y="{y-14}" width="{len(s)*8.4+16}" height="24" fill="#f5f5f5"/>'+text(x,y,s,'label','middle')
def make(slug,title,typ,body,notes,nodes,edges,source):
 svg=f'<svg viewBox="0 0 1280 720" xmlns="http://www.w3.org/2000/svg" role="img" aria-labelledby="{slug}-title {slug}-desc"><title id="{slug}-title">{title}</title><desc id="{slug}-desc">{ESC(notes)}</desc><defs><marker id="arrow" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto"><polygon points="0 0, 8 3, 0 6" fill="#4f5d75"/></marker></defs><rect width="1280" height="720" fill="#f5f5f5"/>'+body+line(40,652,1240,652,False)+text(40,684,'EXPENSE RECORD · '+typ.upper(),'tag')+text(1240,684,'Source contracts define complete behavior','sub','end')+'</svg>'
 
 if typ=='ER / data model': svg=svg.replace('>COMPONENT</text>','>ENTITY</text>')
 fragment=f'<h2>{ESC(title)}</h2><div class="diagram-container">{svg}</div><p>{ESC(notes)}</p><p>Authoritative source: {source}. <a href="{slug}.svg">SVG</a> · <a href="{slug}.png">PNG</a></p>'
 (O/(slug+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><style>{STYLE}</style></head><body><main><p class="tag">MODULE ARCHITECT · DIAGRAM-DESIGN</p>{fragment}</main></body></html>')
 figures.append(dict(slug=slug,title=title,type=typ,nodes=nodes,edges=edges,source=source,fragment=fragment))
