b+=node('presentation',48,256,196,112,'Presentation',['MainActor state'])+node('usecases',304,256,256,128,'ExpenseUseCases',['ImportCoordinator','coordinates all writes'],True)+node('domain',672,116,240,112,'LedgerDomain',['Money / IdentityPolicy'])+node('ports',672,436,240,160,'Application ports',['LedgerStore / Import','Category / Location','Identity / Maintenance'])+node('adapters',1000,416,232,180,'Approved adapters',['CoreData / BillImport','Rules / CoreLocation','IdentityVault / Archive'])
