for a,c,y,s,d in msgs:b+=line(x[a],y,x[c],y,True,d)+label((x[a]+x[c])/2+(100 if abs(a-c)==2 else 0),y-16,s)
for i,(name,sub) in enumerate([('Review UI','explicit user choices'),('ImportCoordinator','pure use-case logic'),('Import + rules','untrusted file / local'),('LedgerStore','one private writer')]):b+=node(str(i),x[i]-112,48,224,108,name,[sub],i==3,tag='ACTOR')
make('import-sequence','Preview then one atomic commit','sequence',b,'Happy path only: parser stages/normalizes, category rules suggest, coordinator compares immutable identities and returns review. Confirm revalidates revision and all decisions inside one durable save; UI obtains the receipt and success through commit result/status. Failure/cancel paths are in STATE-CONTRACT.json. GPS never runs as part of import.',4,9,'MODULE-DESIGN.md transaction + INTERFACES.swift.txt')
# ER source provenance, split from financial relationships.
b=line(264,172,480,172,False)+label(372,152,'1 : 0..N')+line(696,172,960,172,False)+label(828,152,'0..1 : 1..N')+line(1068,252,1068,436,False)+label(1132,344,'N : 1')+path('M 588,436 V 352 Q 588,344 596,344 H 1000 Q 1008,344 1008,336 V 252',False)+label(804,328,'1 : 0..N')+line(264,516,480,516,False)+label(372,496,'1 : N')
b+=node('namespace',48,92,216,160,'AccountNamespace',['# id / provider','random local alias'])+node('identity',480,92,216,160,'SourceIdentity',['# strongKey UNIQUE','economicDigest'])+node('obs',960,92,256,160,'SourceObservation',['batch + row UNIQUE','fingerprint NON-unique'])+node('command',48,436,216,160,'CommandReceipt',['# commandID UNIQUE','requestDigest / result'])+node('batch',480,436,216,160,'BatchReceipt',['# fileDigest UNIQUE','committed result'])+node('entry',960,436,256,160,'Entry',['# UUID','edited values separate'],True)
