b+=node('category',512,48,224,132,'Category',['# id / retired'])+node('entry',512,296,224,160,'Entry',['signed minorUnits','currency / timestamp'],True)+node('refund',48,296,248,160,'RefundLink',['refund UNIQUE','original / revision'])+node('location',960,296,272,160,'LocationEvidence',['kind / collectedAt','consent / accuracy'])+node('override',512,536,224,104,'CategoryOverride',['entry / category'])
b+=text(48,112,'RefundLink: each refund → one original','node-name')+text(48,144,'Original spend has 0..N links; refund 0..1.')+text(48,188,'Linked magnitudes ≤ original; same currency.')+text(960,112,'Also specified in full JSON','node-name')+text(960,144,'MerchantMapping → Category')+text(960,176,'StoreMetadata epoch + revision')+text(960,208,'Selected location / override')
make('ledger-model','Ledger, refunds and location provenance','ER / data model',b,'Entity relationships shown at aggregate level. Entry owns append-only location/override evidence; selected pointers must reference the same Entry. RefundLink has two named Entry relationships shown separately: each link has one original and one refund; an original has 0..N links and a refund 0..1. Pair labels read left-to-right. MerchantMapping and singleton StoreMetadata are text-listed rather than disconnected boxes; full attributes, inverses, constraints and indexes remain authoritative in JSON.',5,5,'CORE-DATA-MODEL.json + MODULE-DESIGN.md invariants')
