b=line(264,196,384,196)+label(324,176,'VALID')+line(600,196,720,196)+label(660,176,'CONFIRM')+line(936,196,1056,196)+label(996,176,'SAVED')+line(492,260,492,468)+label(556,360,'CANCEL')+line(828,260,828,468)+label(900,360,'ROLLBACK')+path('M 720,532 H 648 Q 640,532 640,524 V 252 Q 640,244 632,244 H 600')+label(564,416,'REVIEW AGAIN')
b+=node('parsing',48,132,216,128,'Parsing',['selected file','cancel ≤100 rows'],tag='STATE')+node('review',384,132,216,128,'Review',['explicit decisions','epoch + revision'],tag='STATE')+node('committing',720,132,216,128,'Committing',['recheck all','one durable save'],tag='STATE')+node('committed',1056,132,184,128,'Committed',['receipt replay'],True,tag='STATE')+node('cancelled',384,468,216,128,'Cancelled',['staging deleted'],tag='STATE')+node('recoverable',720,468,216,128,'Recoverable',['locked/full/stale','no partial writes'],tag='STATE')
b+=text(48,84,'Primary lifecycle; full transition/error table in STATE-CONTRACT.json','node-name')+text(48,564,'Unsupported format → stop/reselect.')+text(48,592,'Parse cancel → cancelled.')+text(1016,476,'Cancel during save:')+text(1016,508,'check outcome/receipt;')+text(1016,540,'commit may already win.')
make('import-state','Import transaction and recovery states','state machine',b,'Ordinary state machine chosen because guarded transitions and commit race dominate; not a lifecycle phase map. Idle selection starts parsing. Unsupported and parse failures use the full JSON table. Terminal batches never revert; cleanup failure is committed success. Retry after rollback requires a fresh review. Interrupted save resumes receipt query, not an assumed failure.',6,6,'STATE-CONTRACT.json + MODULE-DESIGN.md')
